// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize, set MinSum to 50, and deposit 100 for Alice
        c.SetMinSum(50);
        c.SetLogFile(address(0xdead));
        c.Initialized();
        address alice = address(0x101);
        vm.deal(alice, 100);
        vm.prank(alice);
        c.Deposit{value: 100}();
        // Now call Collect(30)
        vm.prank(alice);
        c.Collect(30);
        // In the reference, balances[alice] should be 70 (100 - 30).
        // In the bug (addition), it becomes 130 (100 + 30).
        assertTrue(c.balances(alice) == 70);
    }
}

