pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up three accounts: Alice (deposit 100), Bob (deposit 50), and the caller for Collect
        address alice = address(0x1111);
        address bob = address(0x2222);

        vm.deal(alice, 100 ether);
        vm.deal(bob, 50 ether);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Alice deposits 100
        vm.prank(alice);
        c.Deposit{value: 100 ether}();

        // Bob deposits 50
        vm.prank(bob);
        c.Deposit{value: 50 ether}();

        // Bob calls Collect(50)
        vm.prank(bob);
        c.Collect(50 ether);

        // Assert: in reference, Bob's balance becomes 0; in buggy, it becomes 100
        uint256 bobBalance = c.balances(bob);
        assertTrue(bobBalance == 0, "Bob's balance should be 0 after collecting his full deposit");
    }
}

