        try c.Collect{gas: 10000}(10) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        // In the correct contract, the call reverts (insufficient gas), so ok is false, balance remains 10
        // In the buggy contract, balance is set to 0 before the call, ok is false, but balance is 0
