pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious recipient that always reverts
        Reverter reverter = new Reverter();
        address alice = address(reverter);

        // Fund Alice with 10 wei
        vm.deal(alice, 10 wei);

        // Alice deposits 10 wei
        vm.prank(alice);
        c.Deposit{value: 10 wei}();

        // Set MinSum to 10
        c.SetMinSum(10);
        c.Initialized();

        // Alice calls Collect(10) which will revert at the call due to Reverter
        vm.prank(alice);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 10));

        // In the correct contract, balances[alice] remains 10
        // In the buggy contract, balances[alice] is set to 0 before the revert
        assertTrue(c.balances(alice) == 10);
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}

