        c.SetLogFile(address(0x123));
        c.Initialized();

        // Deal ether and deposit to alice
        address alice = address(0xAAAA);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.Deposit{value: 10 ether}();

        // Now alice tries Collect(10) – reference >= MinSum passes, but then fails due to no ether in contract -> reverts
