        bool ok = false;
        vm.prank(alice);
        try c.Collect(10) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference should revert (ok false), bug should succeed (ok true)
        // So we assert that the bug fails: we want the reference's behavior (revert) to pass, bug's (no revert) to fail
        // Thus assertTrue that ok == false to match reference
        assertTrue(ok == false, "Expected revert on Collect in reference");
    }
}

