// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.Deposit{value: 1 ether}();

        bool okP;
        try c.Collect(0) { okP = true; } catch { okP = false; }

        // In reference P, Collect(0) succeeds, MinSum unchanged (0)
        // In mutant M, we can now call SetMinSum after Initialized
        // First need to set log (same as reference)
        c.SetLogFile(address(0xdead));
        c.Initialized();
        // Now call SetMinSum - in reference this reverts, in M it doesn't
        // But to observe divergence: we call SetMinSum in both
        // Actually easier: deploy separate contract for M?
        // No: just test that we can set MinSum after initialization in M but not in P
        // We'll use the same contract, but the test must work for both reference and mutant
        // The test must pass on reference and fail on mutant
        // Actually the scenario: call SetMinSum after Initialized - should revert in reference, succeed in mutant
        // Then MinSum changes, causing Collect(0) behavior to differ

        // Reset state for clarity:
        // Deploy new contract for each?
        // Use a fresh contract per test within same test? No, just SetUp once per contract
        // Better: test that after Initialized, SetMinSum reverts in P but not in M
        // That alone is the divergence, but specification says driven by Collect
        // So do: SetLogFile, Initialized, then try SetMinSum(1) - in P revert, in M succeed
        // Then call Collect(0) - in P it succeeds (MinSum still 0), in M it reverts (MinSum now 1 and 0 < 1)

        // Let's redeploy in test to isolate
        c = new C();
        vm.deal(address(0x1), 10 ether);
        vm.prank(address(0x1));
        c.Deposit{value: 1 ether}();
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Try to change MinSum
        // In reference, this call reverts because initialized
        // In mutant, it works
        (bool okSet,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", 1));

        // Now call Collect(0)
        vm.prank(address(0x1));
        bool okCollect;
        try c.Collect(0) { okCollect = true; } catch { okCollect = false; }

        // Reference: SetMinSum failed (okSet false), MinSum=0, so Collect(0) succeeds (balances>=0 and 0>=0)
        // Mutant: SetMinSum succeeded (okSet true), MinSum=1, so Collect(0) fails (0<1)
        // Therefore reference: okCollect == true, mutant: okCollect == false
        // Also MinSum in reference = 0, in mutant = 1

        assertTrue(okCollect == true); // passes on reference, fails on mutant
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: allow Deposits by setting log and initializing
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Now in reference, SetMinSum(1) reverts; in buggy version it succeeds.
        // We try to call SetMinSum(1) – the test doesn't need to check revert, just the state after.
        // To trigger the divergence, we need Collect to behave differently.
        // Give Alice 5 ether, deposit, then try Collect(0).
        address alice = address(0x1111);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.Deposit{value: 5 ether}();

        // Now call SetMinSum(1) – reference reverts, so MinSum stays 0; buggy sets to 1.
        // We just call it (revert is ok).
        (bool okSet,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", 1));
        // okSet is false for reference (revert), true for buggy.

        // Now call Collect(0) – for reference: balances[alice]=5, MinSum=0 => condition passes, call succeeds;
        // for buggy: balances[alice]=5, MinSum=1 => condition fails, revert.
        vm.prank(alice);
        (bool okCollect,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 0));

        // After these calls, read MinSum via getter.
        uint256 minSumAfter = c.MinSum();

        // Reference: okCollect == true, minSumAfter == 0
        // Buggy: okCollect == false, minSumAfter == 1
        // We assert that the reference holds: Collect succeeded AND MinSum is 0.
        assertTrue(okCollect && minSumAfter == 0);
