import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize MinSum to 1, set log to a dummy address, initialize
        address user = address(0x1234);
        c.SetMinSum(1);
        c.SetLogFile(address(0x5678));
        c.Initialized();

        // Deposit exactly 1 wei from user
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.Deposit{value: 1 wei}();

        // Now attempt to collect 1 wei; wrap in try/catch to observe revert
        bool ok;
        vm.prank(user);
        try c.Collect(1) { ok = true; } catch { ok = false; }

        // In the reference contract, deposit added 1 => balance=1 >= MinSum=1 and >= _am=1, collect succeeds
        // In the buggy contract, deposit subtracted 1 => balance=0 < MinSum=1, collect fails
        assertTrue(ok);
    }
}

