pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: set MinSum, initialize, deploy a malicious receiver that reverts
        c.SetMinSum(10);
        c.Initialized();

        // Deploy a contract that reverts on receiving Ether
        address reverter = address(new Reverter());

        // Fund the actor (address(1)) and deposit 20
        address actor = address(1);
        vm.deal(actor, 30 ether);
        vm.prank(actor);
        c.Deposit{value: 20 ether}();

        // Now actor calls Collect(10) but the call is directed to the reverter address
        // We need to make msg.sender the reverter? No, to trigger the bug we need the call inside Collect to fail.
        // The call inside Collect is to msg.sender. If we call from actor, it sends to actor, which doesn't revert.
        // To make the call fail, we need msg.sender to be a contract that reverts on receive.
        // So we send Collect from the reverter address (via prank) but the reverter has no balance.
        // Instead, we fund the reverter and deposit from it.
        address reverterAddr = address(new Reverter());
        vm.deal(reverterAddr, 30 ether);
        vm.prank(reverterAddr);
        c.Deposit{value: 20 ether}();

        // Now try to Collect(10) from the reverter — inside Collect, the call to msg.sender (reverterAddr) will revert.
        vm.prank(reverterAddr);
        // In reference version, this call will revert because the internal call fails and it hits revert.
        // In buggy version, the else branch is empty, so the state change (balance reduction) persists.
        try c.Collect(10 ether) {
            // If collect succeeds (buggy version), ok;
        } catch {
            // If it reverts (reference version), that's the expected revert behavior.
        }

        // After the collect attempt, check the balance of the reverter.
        // Reference: balance remains 20 (since revert reverted the subtraction).
        // Buggy: balance becomes 10 (because subtraction happened and call failure didn't revert).
        uint256 balanceAfter = c.balances(reverterAddr);

        // The reference contract will have balance 20 ether; the buggy one will have 10 ether.
        // We assert that balanceAfter equals 20 ether, which holds for reference and fails for buggy.
        assertTrue(balanceAfter == 20 ether, "Balance should be unchanged after failed call");
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}

